WITH deduped AS (SELECT id, customer_id, store_id, order_date, status, channel, amount FROM orders QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY shipping_fee NULLS LAST, id) = 1) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, STDDEV_SAMP(amount) AS amount_stddev, AVG(amount) FILTER (WHERE channel = 'mobile') AS mobile_avg_amount, COUNT(*) FILTER (WHERE status = 'CANCELLED') AS cancelled_rows, AVG(amount) FILTER (WHERE status = 'PENDING') AS pending_avg_amount, STDDEV_SAMP(amount) AS amount_stddev_2, APPROX_PERCENTILE(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles FROM deduped GROUP BY activity_month ORDER BY cancelled_rows DESC
